-- Shared SQL/Dart shape cases, with no manufacturer claims.
create function pg_temp.validate_row_fixture(p_value jsonb) returns jsonb language sql as $$
 select public.spec_rows_validate_internal_v1((select case_data->'schema' from rows_cases limit 1),p_value)
$$;
select case when (case_data->>'valid')::boolean
 then lives_ok(format('select public.spec_rows_validate_internal_v1(%L::jsonb,%L::jsonb)',case_data->'schema',case_data->'value'),case_data->>'id')
 else throws_ok(format('select public.spec_rows_validate_internal_v1(%L::jsonb,%L::jsonb)',case_data->'schema',case_data->'value'),'23514',null,case_data->>'id') end
from rows_cases;
select is(pg_temp.validate_row_fixture((select case_data->'value' from rows_cases where case_data->>'id'='canonical_decimal'))#>>'{rows,1,values,width_min}','40','canonical exact decimal readback');

insert into public.spec_definitions(id,key,label,data_type,validation_rules,is_filterable,is_customer_visible)
select '99ba0000-0000-4000-8000-000000000051','rows_fixture','Configuraciones','json',
 jsonb_build_object('rows_schema',case_data->'schema'),false,true from rows_cases limit 1;
insert into public.spec_templates(id,key,name,technical_family,form_contract)
values('99ba0000-0000-4000-8000-000000000050','rows_fixture','Configuraciones fixture','fixture','{"roles":{"rows_fixture":"measurement"}}');
insert into public.spec_template_fields(template_id,spec_definition_id,section_key,sort_order)
values('99ba0000-0000-4000-8000-000000000050','99ba0000-0000-4000-8000-000000000051','measurement',1);
update public.products set spec_template_id='99ba0000-0000-4000-8000-000000000050',is_published=true,show_on_website=true
 where id='99ba0000-0000-4000-8000-000000000020';
create function pg_temp.row_payload(p_id text) returns jsonb language sql as $$
 select jsonb_build_object('99ba0000-0000-4000-8000-000000000051',jsonb_build_object('rows',case_data->'value'))
 from rows_cases where case_data->>'id'=p_id
$$;
create function pg_temp.save_rows(p_value jsonb,p_operation text) returns jsonb language sql as $$
 select public.save_product_with_specs_v1(
 '{"id":"99ba0000-0000-4000-8000-000000000020","name":"Legacy boundary","sku":"SPEC-LEGACY-BOUNDARY"}',false,
 '99ba0000-0000-4000-8000-000000000050',
 (select contract_version from public.spec_templates where id='99ba0000-0000-4000-8000-000000000050'),p_value,
 (select spec_revision from public.products where id='99ba0000-0000-4000-8000-000000000020'),null,p_operation,
 (select updated_at from public.products where id='99ba0000-0000-4000-8000-000000000020'))
$$;
grant select on rows_cases to authenticated;
grant execute on function pg_temp.row_payload(text),pg_temp.save_rows(jsonb,text) to authenticated;
set local role authenticated;
select lives_ok($$select pg_temp.save_rows(pg_temp.row_payload('decimal_precision'),'rows-save')$$,'authenticated aggregate writes paired exact observations');
select is(public.get_product_spec_snapshot_v1('99ba0000-0000-4000-8000-000000000020')#>>'{values,rows_fixture,rows,1,values,width_min}',
 '9007199254740993.1','snapshot keeps the exact value in its own row');
select is(public.get_product_spec_contexts_v1(array['99ba0000-0000-4000-8000-000000000020'::uuid])#>>'{99ba0000-0000-4000-8000-000000000020,rows_fixture,rows,0,values,adapter}',
 'false','context retains false and the row envelope');
select is(public.get_product_spec_typed_configurations_v1(array['99ba0000-0000-4000-8000-000000000020'::uuid])#>>'{99ba0000-0000-4000-8000-000000000020,fields,rows_fixture,value_type}',
 'rows','typed relation transport identifies rows rather than flattening them');
select throws_ok($$select pg_temp.save_rows(pg_temp.row_payload('reversed_within_row'),'rows-invalid')$$,'23514',null,'range reversal cannot partially update aggregate');
select is(public.get_product_spec_snapshot_v1('99ba0000-0000-4000-8000-000000000020')#>>'{values,rows_fixture,rows,1,values,width_min}',
 '9007199254740993.1','rejected aggregate preserves previous configurations');
select throws_ok($$select public.save_product_spec_facts_v1('99ba0000-0000-4000-8000-000000000020',array['99ba0000-0000-4000-8000-000000000051'::uuid],'{}')$$,'23514',null,'old writer cannot erase a structured field by omission');
select throws_ok($$insert into public.spec_facts(tenant_id,subject_type,subject_id,spec_definition_id,value_json)
 values('99ba0000-0000-4000-8000-000000000001','product','99ba0000-0000-4000-8000-000000000020','99ba0000-0000-4000-8000-000000000051',(select case_data->'value' from rows_cases limit 1))$$,'42501',null,'new column cannot bypass product commands');
reset role;
select is((select value_json#>>'{rows,1,values,width_min}' from public.product_spec_values where product_id='99ba0000-0000-4000-8000-000000000020' and spec_definition_id='99ba0000-0000-4000-8000-000000000051'),
 '9007199254740993.1','compatibility projection retains structured rows');
select ok((select display_value like '%9007199254740993.1%' and display_value not like '%schema_version%' from public.get_public_product_technical_specs('99ba0000-0000-4000-8000-000000000001','99ba0000-0000-4000-8000-000000000020') where spec_key='rows_fixture'),
 'storefront renders cells and units, not implementation JSON');
select throws_ok($$update public.spec_definitions set validation_rules='{}' where id='99ba0000-0000-4000-8000-000000000051'$$,'23514',null,'metadata cannot reinterpret populated rows as generic JSON');
select throws_ok($$update public.spec_facts set value_json=null,value_text='[{"bsd":622}]' where subject_id='99ba0000-0000-4000-8000-000000000020'$$,'23514',null,'structured values cannot move into a text fallback');
select ok(exists(select 1 from jsonb_array_elements(public.spec_validate_draft_internal_v1('99ba0000-0000-4000-8000-000000000050',jsonb_build_object('rows_fixture',(select case_data->'value' from rows_cases where case_data->>'id'='partial_is_unknown')))) i where i->>'code'='row_incomplete' and i->>'blocking'='false'),'partial configuration is reported without inventing negative compatibility');
-- A reference's meaning is frozen even before any product adopts it.
insert into public.spec_definitions(id,key,label,data_type,validation_rules,is_filterable,is_customer_visible)
values ('99bb0000-0000-4000-8000-000000000051','rows_review_reference_schema','Reference unit review','json',
 '{"rows_schema":{"version":1,"columns":[{"key":"length","label":"Length","type":"decimal","unit":"mm"}]}}',false,true);
insert into public.product_spec_references(id,technical_family,brand,model,label,fact_values,sources,reviewed_on)
values ('rows-review-reference-schema-v1','fixture','Review','Rows','Rows review',
 '{"99bb0000-0000-4000-8000-000000000051":{"rows":{"schema_version":1,"rows":[{"id":"x","values":{"length":"10"},"sources":["https://example.test/manual"]}]}}}',
 '["https://example.test/manual"]','2026-09-06');
select throws_ok($$update public.spec_definitions set validation_rules=jsonb_set(validation_rules,'{rows_schema,columns,0,unit}','"in"')
 where id='99bb0000-0000-4000-8000-000000000051'$$,'23514',null,'unused reference prevents reinterpretation of units');
select is(public.spec_rows_display_internal_v1(d.validation_rules->'rows_schema',r.fact_values->d.id::text->'rows'),
 'Length: 10 mm','reference retains original meaning after rejected metadata edit')
 from public.spec_definitions d cross join public.product_spec_references r
 where d.id='99bb0000-0000-4000-8000-000000000051' and r.id='rows-review-reference-schema-v1';
select throws_ok($$delete from public.spec_definitions where id='99bb0000-0000-4000-8000-000000000051'$$,
 '23514',null,'unused reference prevents deletion of its row schema');
select throws_ok($$insert into public.product_spec_references(id,technical_family,brand,model,label,fact_values,sources,reviewed_on)
 select 'rows-review-foreign-source','fixture','Review','Other','Foreign source',fact_values,'["https://example.test/other"]','2026-09-06'
 from public.product_spec_references where id='rows-review-reference-schema-v1'$$,
 '23514',null,'row sources must belong to their manufacturer reference');
select throws_ok($$insert into public.product_spec_references(id,technical_family,brand,model,label,fact_values,sources,reviewed_on)
 select 'rows-review-mixed-value','fixture','Review','Other','Mixed value',
 jsonb_set(fact_values,'{99bb0000-0000-4000-8000-000000000051,text}','"extra"'),sources,'2026-09-06'
 from public.product_spec_references where id='rows-review-reference-schema-v1'$$,
 '23514',null,'reference cannot silently discard a mixed scalar alongside rows');
-- Scalar numeric transport is exact at the database boundary as well.
insert into public.spec_definitions(id,key,label,data_type,validation_rules)
values('99ba0000-0000-4000-8000-000000000052','exact_scalar_fixture','Exact scalar','number','{"positive":true}');
