select ok(not(public.get_product_spec_contexts_v1(array['99ba0000-0000-4000-8000-000000000020'::uuid])->'99ba0000-0000-4000-8000-000000000020' ? 'rows_fixture'),'reclassified rows do not become active criteria');
select is((select f#>>'{value,rows,1,values,width_min}' from jsonb_array_elements(public.get_product_spec_snapshot_v1('99ba0000-0000-4000-8000-000000000020')->'unassigned_facts') f where f->>'definition_id'='99ba0000-0000-4000-8000-000000000051'),
 '9007199254740993.1','reclassified row remains inspectable in history');
select is((select f#>>'{rows_schema,columns,0,unit}' from jsonb_array_elements(public.get_product_spec_snapshot_v1('99ba0000-0000-4000-8000-000000000020')->'unassigned_facts') f where f->>'definition_id'='99ba0000-0000-4000-8000-000000000051'),'mm','history retains schema labels and units for readable configurations');
